#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, b;
    cin >> n >> b;
    vector<int> arr1(n);
    for (int i = 0; i < n; i++) {
        cin >> arr1[i];
    }

    vector<int> pf1(n, 0), pf2(n, 0);
    int oddCount = 0, evenCount = 0;
    for (int i = 0; i < n; i++) {
        if (arr1[i] % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }
        pf1[i] = evenCount;
        pf2[i] = oddCount;
    }

    vector<int> diffList;
    int prev = 0;
    for (int i = 1; i < n - 2; i += 2) {
        int x, y;
        if (prev == 0) {
            x = pf1[i];
            y = pf2[i];
        } else {
            x = pf1[i] - pf1[prev];
            y = pf2[i] - pf2[prev];
        }
        if (x == y) {
            diffList.push_back(abs(arr1[i + 1] - arr1[i]));
            prev = i;
        }
    }

    int p = (int)diffList.size();
    vector<int> arr(p);
    for (int i = 0; i < p; i++) {
        arr[i] = diffList[i];
    }

    vector<int> val(p, 1);
    vector<vector<int>> dp(p + 1, vector<int>(b + 1, 0));

    for (int i = 1; i <= p; i++) {
        for (int w = 0; w <= b; w++) {
            if (arr[i - 1] <= w) {
                dp[i][w] = max(val[i - 1] + dp[i - 1][w - arr[i - 1]], dp[i - 1][w]);
            } else {
                dp[i][w] = dp[i - 1][w];
            }
        }
    }

    cout << dp[p][b] << "\n";

    return 0;
}
